from openpyxl import load_workbook
from collections import defaultdict

# Load the workbook and select the active sheet
wb = load_workbook("input.xlsx")
ws = wb.active

# Step 1: Identify the data range
# Find the header row (contains "Mat Doc" and "Doc No")
header_row = None
for row in ws.iter_rows(min_row=1, max_row=10):
    for cell in row:
        if cell.value == "Mat Doc" and cell.column_letter == "D":
            header_row = cell.row
        if cell.value == "Doc No" and cell.column_letter == "E":
            header_row = cell.row

# Find the first data row (after the header)
first_data_row = header_row + 1

# Step 2: Read the data into a structure
mat_doc_col = "D"
doc_no_col = "E"
remark_col = "G"

data = []
for row in ws.iter_rows(min_row=first_data_row, max_col=5, max_row=15):
    mat_doc = ws[f"{mat_doc_col}{row[0].row}"].value
    doc_no = ws[f"{doc_no_col}{row[0].row}"].value
    data.append((mat_doc, doc_no))

# Step 3: Count occurrences of each (Mat Doc, Doc No) combination
counter = defaultdict(int)
for mat_doc, doc_no in data:
    counter[(mat_doc, doc_no)] += 1

# Step 4: Write the Remark values based on the count
for i, (mat_doc, doc_no) in enumerate(data, start=first_data_row):
    count = counter[(mat_doc, doc_no)]
    if count > 1:
        ws[f"G{i}"] = "Multiple"
    else:
        ws[f"G{i}"] = "Single"

# Step 5: Remove all color and border formatting
for row in ws.iter_rows():
    for cell in row:
        cell.fill = None
        cell.border = None

# Step 6: Re-apply thin borders to all populated cells except "Multiple" or "Single"
for row in ws.iter_rows(min_row=first_data_row, max_row=15):
    for cell in row:
        if cell.column_letter == "G":
            if cell.value not in ["Multiple", "Single"]:
                cell.border = "thin"
        else:
            cell.border = "thin"

# Save the workbook
wb.save("output.xlsx")
