from openpyxl import load_workbook
from datetime import datetime, timedelta

# Load the workbook and select the 'Sample Data' sheet
wb = load_workbook('input.xlsx')
ws = wb['Sample Data']

# Step 1: Parse the data
data = []
for row in ws.iter_rows(min_row=4, values_only=True):
    data.append(row)

# Extract headers
headers = next(ws.iter_rows(min_row=3, values_only=True))[0:4]  # Date, Time, Product, Sales

# Step 2: Process the data
product_sales = {}
for i, (date_str, time_str, product, sales) in enumerate(data):
    if sales is None:
        continue
    date = datetime.strptime(date_str, "%Y-%m-%d %H:%M:%S")
    time = datetime.strptime(time_str, "%H:%M:%S")
    full_datetime = datetime.combine(date.date(), time.time())

    # Store sales by product and datetime
    if product not in product_sales:
        product_sales[product] = []
    product_sales[product].append((full_datetime, sales))

# Step 3: Calculate daily sales for each product using the custom 24-hour window
daily_sales = {}
for product, entries in product_sales.items():
    daily_sales[product] = {}
    for i in range(len(entries)):
        current_datetime, current_sales = entries[i]
        if i < len(entries) - 1:
            next_date = entries[i + 1][0].date()
        else:
            continue  # Skip if it's the last entry

        # Define the window: 6:00 AM of current date to 5:59:59 AM of next date
        window_start = datetime.combine(current_datetime.date(), datetime.min.time()) + timedelta(hours=6)
        window_end = datetime.combine(next_date, datetime.min.time()) + timedelta(hours=5, minutes=59, seconds=59)

        # Calculate cumulative sales up to the end of the window
        total_sales = 0
        for dt, sale in entries:
            if dt <= window_end:
                total_sales += sale
            else:
                break  # Stop once we go beyond the window

        # Calculate sales beyond the window (for cumulative subtraction)
        sales_beyond = 0
        for dt, sale in entries:
            if dt > window_end:
                sales_beyond += sale

        # Daily sales = total sales up to window end - sales beyond window
        daily_sales[product][next_date] = total_sales - sales_beyond

# Step 4: Write the results to the answer range G12:J15
# Identify the product columns in the 'Optimal Table' section
product_columns = {}
for col in range(6, 10):  # Columns G to J
    header_cell = ws.cell(row=11, column=col)
    if header_cell.value in ['A', 'B', 'C', 'D']:
        product_columns[header_cell.value] = col

# Write the results
for row_idx, (date, sales) in enumerate(daily_sales['A'].items()):
    for col_idx, product in enumerate(['A', 'B', 'C', 'D']):
        if product in product_columns:
            ws.cell(row=12 + row_idx, column=product_columns[product], value=daily_sales[product].get(date, 0))

# Step 5: Change formatting of G12:J15 from accounting to currency
for row in range(12, 16):
    for col in range(7, 11):  # Columns G to J
        cell = ws.cell(row=row, column=col)
        cell.number_format = '#,##0.00'

# Save the workbook
wb.save('output.xlsx')
