from openpyxl import load_workbook

# Load the workbook
wb = load_workbook("input.xlsx")

# Access the relevant sheets
transactions_sheet = wb["Transactions"]
year_sheet = wb["2022"]

# Define the answer range on the '2022' sheet
answer_range = year_sheet["B5:M8"]

# Read the data from the 'Transactions' sheet
transactions = []
for row in transactions_sheet.iter_rows(min_row=3, max_col=4, values_only=True):
    month, _, amount, category = row
    if month and amount and category:
        transactions.append((month, category, amount))

# Group transactions by month and category
monthly_category_totals = {}
for month, category, amount in transactions:
    if month not in monthly_category_totals:
        monthly_category_totals[month] = {}
    if category not in monthly_category_totals[month]:
        monthly_category_totals[month][category] = 0
    monthly_category_totals[month][category] += amount

# Write the computed values into the answer range
row_index = 0
for month in ["March", "April"]:
    for category in ["Chickens", "Turkeys", "Guineas", "Goats"]:
        cell = answer_range[row_index][0]
        if month in monthly_category_totals and category in monthly_category_totals[month]:
            cell.value = monthly_category_totals[month][category]
        else:
            cell.value = 0
        row_index += 1

# Apply currency formatting to the answer range
for row in answer_range:
    for cell in row:
        cell.number_format = "#,##0.00"

# Save the workbook
wb.save("output.xlsx")
