from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook("input.xlsx")
ws = wb.active

# Read all the data into a list of dictionaries
data = []
for row in ws.iter_rows(min_row=2, max_col=4, values_only=True):
    customer, total, country = row
    data.append({"customer": customer, "total": total, "country": country})

# Group data by customer and country
customer_data = {}
for entry in data:
    customer = entry["customer"]
    country = entry["country"]
    total = entry["total"]

    if customer not in customer_data:
        customer_data[customer] = {}

    if country not in customer_data[customer]:
        customer_data[customer][country] = []

    customer_data[customer][country].append(total)

# For each customer, find the highest invoice amount for non-US countries
max_non_us_invoices = {}
for customer, countries in customer_data.items():
    max_non_us = 0
    for country, totals in countries.items():
        if country != "US":
            max_non_us = max(max_non_us, max(totals))
    max_non_us_invoices[customer] = max_non_us

# Write the computed values to column D (D2:D27)
for row_idx, entry in enumerate(data, start=2):
    customer = entry["customer"]
    country = entry["country"]

    if country != "US":
        ws[f"D{row_idx}"] = country
    else:
        ws[f"D{row_idx}"] = max_non_us_invoices[customer]

# Save the workbook as output.xlsx
wb.save("output.xlsx")
